$meta = get_post_meta(12);
foreach ($meta as $k => $v) {
  if (str_contains($k, "kadence") || str_contains($k, "template") || str_contains($k, "_wp_page")) {
    echo $k, "=", substr(maybe_serialize($v[0]), 0, 180), "\n";
  }
}
